document.addEventListener('DOMContentLoaded', function () {
  const toggleMenuButton = document.getElementById('toggleLeftMenuButton');
  const leftMenu = document.getElementById('leftAccordionMenu');
  const leftMenuNominalWidth = 300;
  const buttonEdgePadding = 15;

  if (toggleMenuButton && leftMenu) {
    const updateToggleButtonAppearance = () => {
        const menuIsOpen = !leftMenu.classList.contains('collapsed');
        if (menuIsOpen) {
            toggleMenuButton.textContent = '✕';
            const buttonWidth = toggleMenuButton.offsetWidth;
            toggleMenuButton.style.left = (leftMenuNominalWidth - buttonWidth - buttonEdgePadding) + 'px';
        } else {
            toggleMenuButton.textContent = '☰';
            toggleMenuButton.style.left = buttonEdgePadding + 'px';
        }
    };
    updateToggleButtonAppearance();
    toggleMenuButton.addEventListener('click', () => {
      leftMenu.classList.toggle('collapsed');
      updateToggleButtonAppearance();
    });
  } else {
    console.error("Toggle menu button or left menu element not found.");
  }

  // Simplified logic: No nesting, just toggle the panel
  const acc = document.getElementsByClassName("accordion-button");
  for (let i = 0; i < acc.length; i++) {
    acc[i].addEventListener("click", function() {
      if (leftMenu && !leftMenu.classList.contains('collapsed')) {
        this.classList.toggle("active");
        const panel = this.nextElementSibling;
        
        if (panel.style.maxHeight) { 
            panel.style.maxHeight = null; 
            panel.classList.remove("show"); 
        }
        else { 
            // The original fix: scrollHeight + 30px for padding
            panel.style.maxHeight = (panel.scrollHeight + 30) + "px"; 
            panel.classList.add("show"); 
        }
      }
    });
  }

   if (acc.length > 0 && acc[0].nextElementSibling && !acc[0].classList.contains('active')) {
    if (leftMenu && !leftMenu.classList.contains('collapsed')) {
        const initialDisplay = leftMenu.style.display;
        if(leftMenu.style.display === 'none') leftMenu.style.display = 'flex';

        const firstPanel = acc[0].nextElementSibling;
        const panelInitialMaxHeight = firstPanel.style.maxHeight;
        const panelInitialDisplay = firstPanel.style.display;

        if (!firstPanel.classList.contains('show')) {
            firstPanel.style.maxHeight = 'none';
            firstPanel.style.display = 'block';
        }
        acc[0].click();
        if (!firstPanel.classList.contains('show')) {
            firstPanel.style.maxHeight = panelInitialMaxHeight || null;
            firstPanel.style.display = panelInitialDisplay || '';
        }
        if(leftMenu.style.display !== initialDisplay) leftMenu.style.display = initialDisplay;
    }
  }
  onOpenCvReady();
});

// -----------------------------------------------------------------------------
// --- FACE TRACKING LOGIC (MediaPipe Face Mesh) -------------------------------
// -----------------------------------------------------------------------------

async function initializeFaceMesh() {
  // We still set the TFJS backend as it's used internally, even with MediaPipe runtime.
  await tf.setBackend('webgl');
  console.log("TensorFlow backend set to WebGL.");

  const model = faceLandmarksDetection.SupportedModels.MediaPipeFaceMesh;
  const detectorConfig = {
    maxFaces: 1,
    refineLandmarks: false,
    // Switch runtime from 'tfjs' to 'mediapipe' for reliability
    runtime: 'mediapipe',
    // Provide the location of the MediaPipe solution files via CDN
    solutionPath: 'https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh',
  };

  try {
    faceMeshDetector = await faceLandmarksDetection.createDetector(model, detectorConfig);
    console.log('Face Mesh detector initialized using MediaPipe runtime.');
  } catch (error) {
    console.error("Failed to initialize Face Mesh detector:", error);
    alert("Error initializing face tracking. Models might be unavailable. Check console.");
  }
}

async function runFaceMeshCycle() {
  try {
    if (faceMeshDetector && videoInput && videoInput.readyState >= 3 && offscreenCtx && faceOverlayCtx) {

      faceOverlayCtx.clearRect(0, 0, faceOverlayCanvas.width, faceOverlayCanvas.height);

      offscreenCtx.drawImage(videoInput, 0, 0, videoInput.videoWidth, videoInput.videoHeight);

      const faces = await faceMeshDetector.estimateFaces(offscreenCanvas, {
        flipHorizontal: false
      });

      if (faces.length > 0) {
        const keypoints = faces[0].keypoints;

        faceOverlayCtx.fillStyle = 'aqua';
        for (const point of keypoints) {
            faceOverlayCtx.beginPath();
            faceOverlayCtx.arc(point.x, point.y, 1.5, 0, 2 * Math.PI);
            faceOverlayCtx.fill();
        }

        const noseTip = keypoints[1];
        const normalizedX = noseTip.x / videoInput.videoWidth;
        const normalizedY = noseTip.y / videoInput.videoHeight;
        smoothedFaceX_global = faceSmoothingFactor * normalizedX + (1 - faceSmoothingFactor) * smoothedFaceX_global;
        smoothedFaceY_global = faceSmoothingFactor * normalizedY + (1 - faceSmoothingFactor) * smoothedFaceY_global;
        latestDetectedFaceX = smoothedFaceX_global;
        latestDetectedFaceY = smoothedFaceY_global;
        window._lastFaceSeenT = performance.now();   // freshness gate for the face-frame view fade
        // A144: feed the loss-boundary learner the RAW normalised position, not
        // the smoothed one — smoothing lags, and the last frame before a loss is
        // exactly where the lag would misreport the boundary.
        bgNoteFaceSeen(normalizedX, normalizedY);
        // A148b HEAD POSE FROM THE FACE. Written exactly as the intrinsics brief
        // states it, so the dependency is visible in the code: fx enters Z and
        // nothing else. X and Y are computed here too and are INDEPENDENT of fx
        // — which is why the existing lateral tracking has never needed the LUT,
        // and why a missing fx degrades to 2-axis tracking rather than to a
        // wrong one. Exposed, not yet driving camera.position.z: that is a
        // product change, and this is the measurement it would rest on.
        try {
            const MI = window.MoebiusIntrinsics;
            if (MI && window._resolvedIntrinsics && keypoints[468] && keypoints[473]) {
                const ipdPx = Math.hypot(keypoints[468].x - keypoints[473].x,
                                         keypoints[468].y - keypoints[473].y);
                window._headPose = MI.headPoseFromFace(window._resolvedIntrinsics, ipdPx,
                                                       noseTip.x, noseTip.y);
            }
        } catch (e) {}
        // A145: grab a template for the boundary probe from an early, CENTRED,
        // settled detection — 30 good frames in, so exposure and auto-focus have
        // converged, and only while the face is near the middle so the crop is
        // not already clipped. Then probe once, before any interaction.
        if (!_faceProbeDone && !window._faceTemplate) {
            window._faceGoodFrames = (window._faceGoodFrames || 0) + 1;
            if (window._faceGoodFrames > 30 &&
                Math.abs(normalizedX - 0.5) < 0.12 && Math.abs(normalizedY - 0.5) < 0.12) {
                let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
                for (const kp of keypoints) {
                    if (kp.x < x0) x0 = kp.x; if (kp.x > x1) x1 = kp.x;
                    if (kp.y < y0) y0 = kp.y; if (kp.y > y1) y1 = kp.y;
                }
                const mw = (x1 - x0) * 0.35, mh = (y1 - y0) * 0.35;   // hair/chin/ears
                x0 -= mw; x1 += mw; y0 -= mh; y1 += mh;
                const w = Math.max(8, x1 - x0), h = Math.max(8, y1 - y0);
                const frame = document.createElement('canvas');
                frame.width = offscreenCanvas.width; frame.height = offscreenCanvas.height;
                frame.getContext('2d').drawImage(offscreenCanvas, 0, 0);
                const cut = document.createElement('canvas');
                cut.width = Math.round(w); cut.height = Math.round(h);
                cut.getContext('2d').drawImage(offscreenCanvas, x0, y0, w, h, 0, 0, cut.width, cut.height);
                window._faceTemplate = { canvas: cut, frame, w, h, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2 };
                window._faceTemplateSource = "the user's own face";
                // A146b: IPD from the iris centres when refineLandmarks gave
                // them (468/473), else the eye-corner pair 33/263 with the
                // canonical-model ratio between the two spans. Fed once.
                try {
                    let ipd = 0;
                    if (keypoints[468] && keypoints[473]) {
                        ipd = Math.hypot(keypoints[468].x - keypoints[473].x, keypoints[468].y - keypoints[473].y);
                    } else if (keypoints[33] && keypoints[263]) {
                        // outer-corner span is ~1.45x the pupil span on the
                        // MediaPipe canonical face; scale so both routes report
                        // the same physical quantity
                        ipd = Math.hypot(keypoints[33].x - keypoints[263].x, keypoints[33].y - keypoints[263].y) / 1.45;
                    }
                    if (ipd > 1 && !window._fovFromFace) {
                        window._fovFromFace = bgEstimateFovFromFace(ipd, offscreenCanvas.width);
                        _camIntrinsics = null;            // force a re-read with the estimate in hand
                        bgReadCameraIntrinsics();
                    }
                } catch (e) {}
                console.log('[A145] face template captured (' + Math.round(w) + 'x' + Math.round(h) +
                    ' px from a centred, settled detection) — re-probing the tracking boundary ' +
                    'with the real face, which supersedes any canonical-face result.');
                _faceProbeDone = false;      // the real face is the better stimulus
                bgProbeFaceEdge();
            }
        }
        if (transformDiv) transformDiv.textContent = `Face Mesh Detected: ${keypoints.length} landmarks`;
        if (initialBaselinePending && canvasElement) {
          setFaceTrackerBaselineOffset(canvasElement);
          initialBaselinePending = false;
        }
      } else {
        if (transformDiv) {
          transformDiv.textContent = 'No face';
        }
        bgNoteFaceLost();   // A144: a loss off-centre is a sample of the boundary
      }
    }
  } catch (error) {
    console.error("Error in detection cycle:", error);
  }
  requestAnimationFrame(runFaceMeshCycle);
}

function setFaceTrackerBaselineOffset(currentCanvas) {
    if (!currentCanvas) {
        console.warn("setFaceTrackerBaselineOffset called without a canvas element.");
        return;
    }
    const cRect = currentCanvas.getBoundingClientRect();
    let oX_calc = 0;
    let oY_calc = 0;

    if (document.fullscreenElement || document.webkitFullscreenElement) {
        oX_calc = 0;
        oY_calc = 0;
    } else {
        const sX = window.screenX || 0, sY = window.screenY || 0;
        const cX = sX + cRect.left, cY = sY + cRect.top;
        const screenWidth = window.screen.width || window.innerWidth;
        const screenHeight = window.screen.height || window.innerHeight;
        const cCX = cX + cRect.width / 2;
        const cCY = cY + cRect.height / 2;
        const mCX = screenWidth / 2;
        const mCY = screenHeight / 2;
        oX_calc = cRect.width > 0 ? (cCX - mCX) / cRect.width : 0;
        oY_calc = cRect.height > 0 ? -(cCY - mCY) / cRect.height : 0;
    }
    baselineFaceTrackerOffsetX = (latestDetectedFaceX - 0.5) + oX_calc;
    baselineFaceTrackerOffsetY = (latestDetectedFaceY - 0.5) + oY_calc;
}

// -----------------------------------------------------------------------------
// --- DEBUG INFORMATION & UI UPDATES ------------------------------------------
// -----------------------------------------------------------------------------

function updateActualDebugInfo(sourceWidth, sourceHeight, segmentsW, segmentsH, numVertices) {
    if (sourceResolutionDisplayElement) {
        sourceResolutionDisplayElement.textContent = `${sourceWidth || '-'}x${sourceHeight || '-'}`;
    }
    if (actualVerticesDisplayElement) {
        if (segmentsW && segmentsH && numVertices) {
            actualVerticesDisplayElement.textContent = `${segmentsW}x${segmentsH} (${numVertices.toLocaleString()})`;
        } else {
            actualVerticesDisplayElement.textContent = '-x- (-)';
        }
    }
}

function calculateAndDisplayOptimalVertices() {
    if (optimalVerticesDisplayElement) {
        if (currentSourceWidthForOptimalCalc > 0 && currentSourceHeightForOptimalCalc > 0) {
            let optimalSegmentsW = Math.max(1, Math.round((currentSourceWidthForOptimalCalc / MESH_DENSITY_FACTOR) - 1));
            let optimalSegmentsH = Math.max(1, Math.round((currentSourceHeightForOptimalCalc / MESH_DENSITY_FACTOR) - 1));
            let optimalTotalVertices = (optimalSegmentsW + 1) * (optimalSegmentsH + 1);
            optimalVerticesDisplayElement.textContent = `${optimalSegmentsW}x${optimalSegmentsH} (${optimalTotalVertices.toLocaleString()})`;
        } else {
            optimalVerticesDisplayElement.textContent = '-x- (-)';
        }
    }
}


// -----------------------------------------------------------------------------
// --- SHADER & MATERIAL CREATION ----------------------------------------------
// -----------------------------------------------------------------------------

// --- createShaderMaterial ---
// MODIFIED: Fixed 'shouldDiscard' redefinition error in fragment shader debug logic
function createShaderMaterial(mode, mainTexture, depthTextureForMode, alphaTexture) {
    const materialUniforms = {
        u_portalPlaneDepthNorm: { value: currentNormPortalPlane },
        u_worldOuterVolumeDepth: { value: outerVolumeDepth },
        u_worldInnerVolumeDepth: { value: innerVolumeDepth },
        displacementBias: { value: 0.0 },
        // A167: slides the whole depth volume back so its NEAREST extent lands
        // on the viewport surface — nothing protrudes through the glass. See
        // bgEmbedVolume — A209: OFF by default (user decision); the uniform
        // reads 0 unless the immersive package is opted into.
        u_embedOffset: { value: 0.0 },
        u_useRayReproject: { value: false },                 // A59f: true anamorphic reprojection (opt-in)
        u_refEye: { value: new THREE.Vector3(0, 0, 0.2) },   // fixed reference (authoring) eye, world space
        // A171: the aperture crop. Off unless the outer matte is absent — see
        // apertureCropGLSL. Only what is BEHIND u_apertureZ is cropped.
        u_popExtra:       { value: 0.0 },
        u_popH:           { value: 0.2 },
        u_popTanTheta:    { value: 1.0 },
        u_popMargin:      { value: 0.0 },
        u_popLambda:      { value: 1.0 },
        u_apertureCrop:   { value: 0.0 },
        u_apertureCenter: { value: new THREE.Vector2(0, 0) },
        u_apertureHalf:   { value: new THREE.Vector2(1e6, 1e6) },
        u_apertureZ:      { value: 0.0 },
        u_eyeWorld:       { value: new THREE.Vector3(0, 0, 0.2) },
        u_textureSize: { value: new THREE.Vector2(1, 1) },
        u_depthPeekActive: { value: depthPeekActive },
        u_depthPeekValue: { value: depthPeekValue },
        u_depthPeekTolerance: { value: depthPeekTolerance },
        u_splitPeekActive: { value: false },
        u_splitPeekValue: { value: 0.0 },
        u_metricScale: { value: metricScaleFactor },
        u_edgeMask: { value: null },
        u_useEdgeMask: { value: false },
        u_isBackgroundLayer: { value: false },
        u_resolution: { value: new THREE.Vector2(renderer.domElement.width, renderer.domElement.height) },

        // --- NEW UNIFIED GAP UNIFORMS ---
        u_useDepthGrad: { value: document.getElementById('useDepthGradCheck')?.checked || true },
        u_depthGradThreshold: { value: parseFloat(document.getElementById('depthGradThresholdSlider')?.value) || 0.02 },
        u_cutSharp: { value: false }, // RUNG cut: set by the certified-source gate
        u_sdHighlight: { value: false },   // A36: SD-region preview
        u_sdMask: { value: null },
        u_sdMaskTexel: { value: new THREE.Vector2(1/1024, 1/1024) },
        // A210: the SOURCE FRAME rect in world x/y (the content mesh rect).
        // The user's classification rule: anything OUTSIDE this rect is
        // OUTPAINT demand, anything inside is INPAINT (disocclusions). The
        // 1e6 default means "everything counts as in-frame" until the
        // per-frame sync publishes the real rect — a missing sync degrades
        // to the old behaviour, never to false orange.
        u_frameC: { value: new THREE.Vector2(0, 0) },
        u_frameH: { value: new THREE.Vector2(1e6, 1e6) },
        u_frameZ: { value: 0.0 },
        u_useBgIslands: { value: false },  // A58: quick-bake plate renders ONLY inside the dilated disocclusion band (hole-only islands, not a full clone)
        u_bgIslandMask: { value: null },
        
        u_useSobel: { value: document.getElementById('useSobelCheck')?.checked || false },
        u_sobelThreshold: { value: parseFloat(document.getElementById('sobelThresholdSlider')?.value) || 0.1 },

        u_useLuma: { value: document.getElementById('useLumaCheck')?.checked || false },
        u_lumaThreshold: { value: parseFloat(document.getElementById('lumaThresholdSlider')?.value) || 0.1 },

        u_useChroma: { value: document.getElementById('useChromaCheck')?.checked || false },
        u_chromaThreshold: { value: parseFloat(document.getElementById('chromaThresholdSlider')?.value) || 0.1 },

        u_useCrease: { value: document.getElementById('useCreaseCheck')?.checked || false },
        u_creaseThreshold: { value: parseFloat(document.getElementById('creaseThresholdSlider')?.value) || 0.2 },
        
        u_useCurvature: { value: document.getElementById('useCurvatureCheck')?.checked || false },
        u_curvatureThreshold: { value: parseFloat(document.getElementById('curvatureThresholdSlider')?.value) || 1.0 },
        
        u_useUVStretch: { value: document.getElementById('useUVStretchCheck')?.checked || false },
        u_uvStretchThreshold: { value: parseFloat(document.getElementById('uvStretchThresholdSlider')?.value) || 0.5 },

        u_useGrazingAngle: { value: document.getElementById('useGrazingAngleCheck')?.checked || false },
        u_grazingAngleThreshold: { value: parseFloat(document.getElementById('grazingAngleThresholdSlider')?.value) || 0.2 },

        // Band-gated stretch cut (set by buildBackgroundLayer once the plug
        // exists): u_bandMask = source-space disocclusion band (dilated), the
        // ONLY region where the FG may discard; the trigger is the
        // sampled-vs-interpolated depth mismatch (see unifiedGapLogicGLSL).
        u_useBandCut: { value: false },
        u_bandCutAll: { value: false },  // A35: stretch net ungated by the band (pre-torn bake: reveals are always backed)
        u_bandMask: { value: null },
        u_bandCutMismatch: { value: 0.01 },
        u_bandCutMaxGrad: { value: 0.04 },
        u_bandCutUvRate: { value: 0.0 }, // 0 = stretch test off until armed
        u_cutContactRamp: { value: 1.0 }, // A84: contact-rubber exemption from the mask gate
        // A241 PER-FRAGMENT TEAR (window._fragTear, measured arm): the A212 fold law
        // evaluated at the CURRENT pose in the fragment shader instead of baked at
        // the cone rim. u_texelsPerPxRest = the foreground's texel density at rest.
        u_fragTear: { value: 0.0 },
        u_fragTearGate: { value: 1.0 },      // 1 = only where the bake's demand mask backs the fragment (A212's scan gate)
        u_fragTearFactor: { value: 2.0 },    // stretch beyond which a cell has folded: shift span > its own extent (A212/a102)
        u_texelsPerPxRest: { value: 0.0 },
        u_poseFrac: { value: 0.0 },          // A241b: |eye offset| / rim offset, updated every frame
        u_restClip: { value: new THREE.Vector2(0, 0) },   // A245: the frame's rest footprint in NDC half-extents; the plug is not drawn outside it (0 = off)
        // A189 THE BAND CUT MEASURES PER RENDERED PIXEL AND ITS THRESHOLDS NAME
        // THE CANVAS. dFdx(vUv) and fwidth() are per-fragment-quad, so every
        // quantity in the cut is "per pixel of whatever we are rasterising
        // into", while u_bandCutUvRate is bgBandCutStretchFrac / renderer width
        // and u_bandCutMaxGrad is depth per canvas pixel. Those agree only while
        // the bound target IS the canvas.
        //
        // The a130 simulated viewer breaks that: pass 1 binds a buffer
        // SV_SUPERSAMPLE times wider, so every measurement shrinks by that
        // factor against a threshold that did not move — the undithered
        // `uvRate < u_bandCutUvRate` branch starts deleting solid regions and
        // the a83 dithered band eats into the figure. Measured on the star:
        // the astronaut renders see-through and striped AT REST, and a black
        // wedge opens at pitch 27 (a188/a188c).
        //
        // u_pxScale converts a measurement back to canvas pixels. 1.0 on every
        // normal frame, so the shipped path is untouched by construction; the
        // simulated viewer sets it to its own supersample factor for pass 1 and
        // restores it after. Verified: with it applied, pass 1 differs from the
        // cut-disabled arm by 0.00 mean luma at rest and 0.08 at pitch 27.
        u_pxScale: { value: 1.0 },
        // --------------------------------

        u_alphaMap: { value: alphaTexture },
        u_hasAlphaMap: { value: (alphaTexture !== null) },
    };

    let specificUniforms, vertexShaderSource, fragmentShaderSource;

    const commonVertexVaryings = `
        varying vec2 vUv;
        varying float vFoldAt;   // A241b: pose fraction at which this vertex's cells fold (>= 2 = never)
        varying vec4 vClip;      // A245: clip-space position for the rest-footprint clip
        varying float vNormalizedDepth;
        varying float vClipW;
        varying vec3 vViewPosition;
        varying vec3 vWorldPos;   // A171: the displaced point in WORLD space
    `;

    // --- THE UNIFIED FRAGMENT SHADER HEAD ---
    const fragmentShaderHead = `
        uniform sampler2D u_edgeMask; uniform bool u_useEdgeMask;
        uniform bool u_isBackgroundLayer; uniform vec2 u_resolution;
        uniform bool u_depthPeekActive; uniform float u_depthPeekValue; uniform float u_depthPeekTolerance;
        uniform bool u_splitPeekActive; uniform float u_splitPeekValue;
        uniform sampler2D u_alphaMap; uniform bool u_hasAlphaMap;
        uniform vec2 u_textureSize;

        // --- GAP STRATEGY UNIFORMS ---
        uniform bool u_useDepthGrad;   uniform float u_depthGradThreshold;
        uniform bool u_cutSharp; // RUNG cut: certified-asset threshold override (0.008)
        uniform bool u_sdHighlight; uniform sampler2D u_sdMask; uniform vec2 u_sdMaskTexel;
        uniform vec2 u_frameC; uniform vec2 u_frameH;   // A210: source frame rect, world x/y
        uniform float u_frameZ;                         // A210b: the frame plane (ray test)
        uniform bool u_useBgIslands; uniform sampler2D u_bgIslandMask;
        uniform bool u_useSobel;       uniform float u_sobelThreshold;
        uniform bool u_useLuma;        uniform float u_lumaThreshold;
        uniform bool u_useChroma;      uniform float u_chromaThreshold;
        uniform bool u_useCrease;      uniform float u_creaseThreshold;
        uniform bool u_useCurvature;   uniform float u_curvatureThreshold;
        uniform bool u_useUVStretch;   uniform float u_uvStretchThreshold;
        uniform bool u_useGrazingAngle; uniform float u_grazingAngleThreshold;
        uniform bool u_useBandCut;     uniform sampler2D u_bandMask;
        uniform bool u_bandCutAll;
        uniform float u_bandCutMismatch; uniform float u_bandCutMaxGrad;
        uniform float u_bandCutUvRate;
        uniform float u_cutContactRamp;
        uniform float u_fragTear; uniform float u_fragTearGate; uniform float u_fragTearFactor; uniform float u_texelsPerPxRest; uniform float u_poseFrac;   // A241
        uniform float u_pxScale;       // A189: rendered pixels -> canvas pixels (1.0 normally)

        // --- A171 APERTURE CROP ---
        uniform float u_apertureCrop;    // 0 = off (the opaque matte is doing the job)
        uniform vec2  u_apertureCenter;
        uniform vec2  u_apertureHalf;
        uniform float u_apertureZ;
        uniform vec3  u_eyeWorld;

        varying vec2 vUv;
        varying float vFoldAt;
        varying vec4 vClip; uniform vec2 u_restClip;   // A245
        varying float vNormalizedDepth;
        varying float vClipW;
        varying vec3 vViewPosition;
        varying vec3 vWorldPos;

        // Helper: Luminance
        float getLuma(vec3 rgb) {
            return dot(rgb, vec3(0.299, 0.587, 0.114));
        }
        
        // Helper: getDepth (will be defined by each mode)
        float getDepth(vec2 uv);
    `;

    const unifiedGapLogicGLSL = `
        bool isGap = false;
        // Define 'center' depth early as it is used by Curvature (Laplacian)
        #define center getDepth(vUv)

        // --- 0. BAND-GATED STRETCH CUT (plug reveal) ---
        // A fragment whose sampled depth (center) disagrees with its
        // vertex-interpolated depth (vNormalizedDepth) sits on a triangle
        // spanning a depth cliff. Whether that triangle is a mid-parallax
        // RUBBER BAND (the smear that reads as a streak) or just a rest-state
        // silhouette cell is decided by the screen-space ramp rate: at rest
        // the cliff crosses its cell in ~2px (fwidth large); a stretched
        // triangle ramps the same cliff over tens of px (fwidth tiny). Cut
        // only the stretched case, only inside the plug band (where the BG
        // layer is guaranteed opaque) — thin features stay intact at rest,
        // and no naked holes can ever open.
        // A35: with u_bandCutAll the net applies to the BACKGROUND plate
        // too — the plate is a monolithic grid whose own internal cliffs
        // (far-surface vs far-surface) rubber-band exactly like FG cliffs;
        // a discarded fragment shows black, which is the honest answer for
        // content no capture carries (same statement as the view fade).
        // --- A241 PER-FRAGMENT TEAR (view-dependent A212) ---
        // A212 tears a foreground cell at bake time when its rim-pose shift span
        // exceeds its own extent, i.e. when the cell would be stretched to 2x or
        // folded at the cone rim — and the tear is then open at EVERY pose,
        // including rest, where the plate shows through (Addendum 177 item 5:
        // 2,606 px of wash where source pixels should be). Here the same law is
        // applied to the fragment's actual stretch at the current pose: the
        // texel density along the most-stretched direction (minor singular value
        // of the texel-space Jacobian, the a81/a82 rotation-free invariant) against
        // the density at rest. At rest the ratio is 1 and nothing is cut; at the
        // rim exactly the A212 cells cross 2x. Folded cells are back-facing and
        // cut outright. Gated like A212's scan gate by the bake's demand mask.
        // A241b (u_fragTear == 2): the same law carried by the VERTICES. At bake
        // each cell's fold point is the pose fraction f at which its rim shift
        // span times f exceeds its extent (A212's test made continuous in the
        // eye offset); a vertex carries the minimum over its cells (A111's
        // predicate: a texel incident to any folding cell). The fragment
        // compares the interpolated fold point with the current pose fraction —
        // a continuous field, no per-quad derivative noise, no speckle.
        // A245: the plug's margin exists to cover what the foreground vacates INSIDE the frame's rest
        // footprint; outside that footprint there is nothing to cover at any pose (the outpaint class
        // is the SD stage's), so the plug is not drawn there — rest stays pixel-faithful to the frame.
        if (u_isBackgroundLayer && u_restClip.x > 0.0) { vec2 ndc = vClip.xy / max(vClip.w, 1e-6); if (abs(ndc.x) > u_restClip.x || abs(ndc.y) > u_restClip.y) discard; }
        if (u_fragTear > 1.5 && !u_isBackgroundLayer && !isGap) {
            if (u_poseFrac > vFoldAt) isGap = true;
        } else if (u_fragTear > 0.5 && !u_isBackgroundLayer && !isGap) {
            bool gateOk = (u_fragTearGate < 0.5) || (texture2D(u_sdMask, vUv).r > 0.25);
            if (gateOk) {
                float pxS = (u_pxScale > 0.0) ? u_pxScale : 1.0;
                vec2 jx = dFdx(vUv) * u_textureSize, jy = dFdy(vUv) * u_textureSize;   // texels per rendered px
                float jmax = max(length(jx), length(jy));
                float svMin = abs(jx.x * jy.y - jx.y * jy.x) / max(jmax, 1e-9);        // texels per px along the most stretched direction
                float stretch = u_texelsPerPxRest / max(svMin * pxS, 1e-9);
                if (stretch > u_fragTearFactor || !gl_FrontFacing) isGap = true;
            }
        }
        if (u_useBandCut && (!u_isBackgroundLayer || u_bandCutAll) && !isGap) {
            if (u_bandCutAll || texture2D(u_bandMask, vUv).r > 0.5) {
                // (a) STRETCH: UV advances far slower per screen px than an
                // unstretched cell would (the derivative is constant across a
                // triangle, so this catches the WHOLE rubber band — including
                // the near half, where the depth mismatch is zero by
                // construction). u_bandCutUvRate = fraction-of-expected rate.
                // A81/A82: rubber from parallax stretches ONE direction —
                // max() of the two axis rates is blind to it (a stretched
                // filament keeps a normal rate on the other axis), and
                // min() of the axis LENGTHS is still blind when the
                // stretch is DIAGONAL (the warrior's helmet spoke-rays:
                // both screen-aligned lengths read mid-magnitude). The
                // rotation-free invariant is the minor SINGULAR VALUE of
                // the UV Jacobian, sv_min = |det| / sv_max, which
                // collapses for extreme stretch in ANY direction. Cut past
                // ~3x: filament and spoke rubber run 10-50x, glancing
                // walls and mild anamorphic content (the protected
                // realtime look) sit at 1.5-2.5x (a 2x cut speckled the
                // troll walls white — measured, Addendum 85).
                // A189: dFdx/dFdy are per RENDERED pixel and the thresholds
                // below are per CANVAS pixel, so both rates carry u_pxScale.
                // The Jacobian scales by 1/S under an S-times-wider target, so
                // uvRate does too and svMinS = |det|/uvRate scales by 1/S as
                // well (|det| by 1/S^2). One factor on each restores them.
                // pxS defaults to 1 when the uniform is absent. An unbound
                // sampler-less float reads 0 in GLSL, and 0 here would make
                // every rate zero and "uvRate < threshold" unconditionally
                // true — the whole layer would vanish. A material that does
                // not carry the uniform must get the shipped behaviour, not
                // the worst possible one.
                float pxS = (u_pxScale > 0.0) ? u_pxScale : 1.0;
                vec2 jxS = dFdx(vUv), jyS = dFdy(vUv);
                float uvRaw  = max(length(jxS), length(jyS));
                float uvRate = uvRaw * pxS;
                float svMinS = (abs(jxS.x * jyS.y - jxS.y * jyS.x) / max(uvRaw, 1e-9)) * pxS;
                // A83: GRADED cut. A binary threshold at 3x oscillates on
                // terraced grazing walls at beyond-fade poses — the wall's
                // stretch crosses the line row by row and the discard
                // renders as comb banding (measured at troll 0.358: comb
                // with the cut, none without). Keep the hard cut for true
                // rubber (>5x), dither-fade the 5x..2.8x band so the edge
                // has no line to comb along; in-band content (<=2.5x)
                // untouched. u_bandCutUvRate = 0 still disables entirely.
                float svRatio = svMinS / max(u_bandCutUvRate, 1e-9);
                float svCutProb = clamp(1.0 - (svRatio - 0.2) / 0.16, 0.0, 1.0);
                float svDith = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
                // A84: the cut's safety premise — "the plate backs every
                // reveal" — is FALSE on un-revealed ground and at frame
                // margins, where a discard is a naked pixel (user-reported
                // speckle field across the near dune at +y poses). Gate the
                // directional cut by the SD mask: only fragments whose bake
                // proved a genuine reveal behind them may discard. Ground
                // stretch outside the mask is the legitimate realtime look.
                // A211 REFUTED, REMOVED (rule 7): dropping this mask gate when a plate
                // exists behind the FG ("a discard reveals plate, not a hole") measured
                // staff streak -0.1%, ship -0.4%, ground speckle +30.7% (harness/
                // a211_cut.js, user's pose). The gate was never what protects the
                // staff/ship streamers: uvRate takes the MAX jacobian axis, and a
                // 1-2px filament stretched along ONE axis keeps a healthy cross-axis,
                // so it never classifies as stretched for ANY gate. The taffy blocker
                // is the classifier, not the backing (-> A212: the screen-space gap
                // pass, which does see these pixels, as the discard authority).
                bool svBacked = texture2D(u_sdMask, vUv).r > 0.25;
                // A84: the mask gate has a blind class — CONTACT RUBBER.
                // Sub-tear source ramps (figure-ground contacts; measured
                // at the astronaut boot: 0.016..0.024 depth per texel vs
                // 0.002..0.004 on open ground) never tear, never
                // disocclude, and so never enter the SD mask at any
                // dilation radius — the gate protects their streamers
                // unconditionally. A fragment that is BOTH hard-stretched
                // (>=5x, the true-rubber class; the dithered 2.8..5x band
                // is what speckled legitimate grazing ground pre-a84 and
                // stays strictly mask-gated) AND sits on a cliff-scale
                // source ramp is rubber by construction: it may cut
                // without mask backing. Ramp threshold reuses
                // u_bandCutMismatch (0.01), the midpoint of the measured
                // class gap and this block's existing cliff scale.
                if (!svBacked && u_cutContactRamp > 0.5 &&
                    (uvRate < u_bandCutUvRate || svRatio <= 0.2)) {
                    float rampX = abs(getDepth(vUv + vec2(u_sdMaskTexel.x, 0.0)) -
                                      getDepth(vUv - vec2(u_sdMaskTexel.x, 0.0)));
                    float rampY = abs(getDepth(vUv + vec2(0.0, u_sdMaskTexel.y)) -
                                      getDepth(vUv - vec2(0.0, u_sdMaskTexel.y)));
                    if (0.5 * max(rampX, rampY) > u_bandCutMismatch) svBacked = true;
                }
                bool stretched = (u_bandCutUvRate > 0.0) && svBacked &&
                                 (uvRate < u_bandCutUvRate || (svCutProb > 0.0 && svDith < svCutProb));
                // (b) MISMATCH: sampled-vs-interpolated depth disagreement,
                // gated to slow ramps so rest-state cliffs are exempt.
                // A189: fwidth is depth per RENDERED pixel and u_bandCutMaxGrad
                // is depth per canvas pixel — the same mismatch as the rates
                // above, and the same one-factor correction. Not separately
                // convicted by a188c (the two rate branches were), but it is
                // the identical unit error in the identical block and leaving
                // it would make the fix depend on which branch happened to fire.
                bool torn = abs(center - vNormalizedDepth) > u_bandCutMismatch &&
                            (fwidth(vNormalizedDepth) * pxS) < u_bandCutMaxGrad;
                if (stretched || torn) isGap = true;
            }
        }

        // --- 1. GENERATORS (Depth & Texture) ---
        
        // A. Depth Gradient (Standard Derivatives)
        if (u_useDepthGrad) {
            float depthRate = fwidth(vNormalizedDepth);
            // RUNG cut: on the certified (sharpened) asset the skin class
            // (0.008-0.03 steps) discards onto the clean plate; smooth
            // interiors measure < 0.008/px everywhere (0 false discards).
            if (depthRate > (u_cutSharp ? 0.008 : u_depthGradThreshold)) isGap = true;
        }

        // B. Luma Derivative (Sharp texture detail)
        if (u_useLuma && !isGap) {
            float luma = getLuma(originalColor.rgb);
            float lumaRate = fwidth(luma);
            if (lumaRate > u_lumaThreshold) isGap = true;
        }

        // C. Chroma Derivative (Color edges)
        if (u_useChroma && !isGap) {
            vec3 rgbRate = fwidth(originalColor.rgb);
            if (length(rgbRate) > u_chromaThreshold) isGap = true;
        }

        // D. 3x3 Sobel (High quality depth)
        if (u_useSobel && !isGap) {
            vec2 texel = 1.0 / u_textureSize;
            float t  = getDepth(vUv + vec2( 0.0,  texel.y));
            float b  = getDepth(vUv + vec2( 0.0, -texel.y));
            float l  = getDepth(vUv + vec2(-texel.x,  0.0));
            float r  = getDepth(vUv + vec2( texel.x,  0.0));
            float tl = getDepth(vUv + vec2(-texel.x,  texel.y));
            float tr = getDepth(vUv + vec2( texel.x,  texel.y));
            float bl = getDepth(vUv + vec2(-texel.x, -texel.y));
            float br = getDepth(vUv + vec2( texel.x, -texel.y));
            // Note: t and center (vUv) are slightly different here due to how Sobel is defined vs Laplacian
            float dX = tr + 2.0*r + br - (tl + 2.0*l + bl);
            float dY = bl + 2.0*b + br - (tl + 2.0*t + tr);
            if (sqrt(dX*dX + dY*dY) > u_sobelThreshold) isGap = true;
        }

        // --- 2. ADVANCED GENERATORS (Curvature & Crease) ---

        // F. Surface Curvature (Depth Laplacian Implementation)
        // We prioritize this over the normal-based approach as it is more stable.
        if (u_useCurvature && !isGap) {
            vec2 texel = 1.0 / u_textureSize;

            // Laplacian Kernel (0, 1, 0 / 1, -4, 1 / 0, 1, 0)
            float laplacian = getDepth(vUv + vec2(0.0, texel.y))
                            + getDepth(vUv + vec2(0.0, -texel.y))
                            + getDepth(vUv + vec2(texel.x, 0.0))
                            + getDepth(vUv + vec2(-texel.x, 0.0))
                            - 4.0 * center;

            // Scaling factor is needed because depth is normalized (0-1). 
            // This factor depends on the scene scale and depth range. 50.0 is a reasonable starting point.
            float curvature = abs(laplacian) * 50.0;

            // Threshold (default 1.0) will likely need tuning for this implementation.
            if (curvature > u_curvatureThreshold) isGap = true;
        }

        // --- 3. NORMAL-BASED CALCULATIONS (Crease and Inhibitors) ---
        
        vec3 faceNormal = vec3(0.0);
        vec3 unnormalizedNormal = vec3(0.0);
        float normalLength = 0.0;

        // Calculate normals only if needed for Crease (MND) or Grazing Angle
        // We check u_useCrease OR (if a gap exists AND u_useGrazingAngle is on)
        if (u_useCrease || (isGap && u_useGrazingAngle)) {
            // Calculate derivatives of view-space position
            vec3 dPosDx = dFdx(vViewPosition);
            vec3 dPosDy = dFdy(vViewPosition);
            
            // Calculate the UNNORMALIZED normal
            unnormalizedNormal = cross(dPosDx, dPosDy);
            normalLength = length(unnormalizedNormal);

            // Normalize safely for Grazing Angle
            if (normalLength > 1e-6) {
                faceNormal = unnormalizedNormal / normalLength;
            } else {
                // Fallback for degenerate geometry (e.g., zero area triangle)
                // Using a safe default prevents NaN propagation, though Grazing Angle won't work here.
                faceNormal = vec3(0.0, 0.0, 1.0); 
            }
        }

        // E. Normal Discontinuity (Crease Generator) - ROBUST IMPLEMENTATION (MND)
        if (u_useCrease && !isGap) {
            // Ensure we don't divide by zero if the normal length is too small
            if (normalLength > 1e-6) {
                // Robust approximation: length(fwidth(Unnormalized)) / Length
                // This isolates the change in orientation.
                float crease = length(fwidth(unnormalizedNormal)) / normalLength;

                // The threshold (default 0.2) may need tuning for this implementation.
                if (crease > u_creaseThreshold) isGap = true;
            }
        }

        // --- 4. INHIBITORS (AND NOT Logic) ---
        
        if (isGap) {
            // A. UV Stretch (Inhibit on slanted surfaces)
            if (u_useUVStretch) {
                vec2 dUvDx = dFdx(vUv);
                vec2 dUvDy = dFdy(vUv);
                float uvStretch = max(length(dUvDx), length(dUvDy));
                // Scale threshold by texture size for consistent results
                if (uvStretch * max(u_textureSize.x, u_textureSize.y) > u_uvStretchThreshold * 100.0) {
                    isGap = false;
                }
            }

            // B. Grazing Angle (Inhibit on smooth silhouettes)
            if (u_useGrazingAngle && isGap) { // Check isGap again
                // Use the safely calculated faceNormal.
                // Only apply if the normal calculation was successful.
                if (normalLength > 1e-6) {
                    vec3 viewDir = normalize(-vViewPosition);
                    float incidence = abs(dot(faceNormal, viewDir));
                    if (incidence < u_grazingAngleThreshold) {
                        isGap = false;
                    }
                }
            }
        }

        // --- 5. FALLBACK (External Post-Processed Mask) ---
        if (u_useEdgeMask && !isGap) {
            vec2 screenUv = gl_FragCoord.xy / u_resolution;
            if (texture2D(u_edgeMask, screenUv).r > 0.5) isGap = true;
        }

        // The BACKGROUND LAYER never discards: it is the completed layer whose
        // whole purpose is to be visible where the foreground layer opens.
        if (isGap && !u_isBackgroundLayer) discard;
    `;

    const baseVertexShaderPrefix = `
        ${commonVertexVaryings}
        attribute float aFoldAt;
        uniform float u_portalPlaneDepthNorm;
        uniform float u_worldOuterVolumeDepth;
        uniform float u_worldInnerVolumeDepth;
        uniform float displacementBias;
        uniform float u_embedOffset;
        uniform bool  u_useRayReproject;
        uniform vec3  u_refEye;
        // A174: the tapered pop-out. Declared here as well as in the fragment
        // head — same uniforms object, two stages.
        uniform float u_popExtra;      // 0 = no pop-out
        uniform float u_popH;          // eye -> portal distance
        uniform float u_popTanTheta;   // tan of the committed cone half-angle
        uniform float u_popMargin;     // one rendered pixel, in world units
        uniform float u_popLambda;     // 1 - 1/R, the scene's own stretch tolerance
        uniform vec2  u_apertureCenter;
        uniform vec2  u_apertureHalf;
    `;
    
    const viewSpaceDisplacementLogic = `
        float displacement = 0.0;
        if (vNormalizedDepth < u_portalPlaneDepthNorm) {
            float t = smoothstep(0.0, u_portalPlaneDepthNorm, vNormalizedDepth);
            displacement = mix(-u_worldOuterVolumeDepth, 0.0, t);
        } else {
            float t = smoothstep(u_portalPlaneDepthNorm, 1.0, vNormalizedDepth);
            // A174: growing the INNER half by u_popExtra leaves the portal plane
            // (t = 0) and the far extent untouched and moves only the near
            // extent, so the pop-out costs no rescale of the background — which
            // is the whole reason a172 rejected translating the volume.
            displacement = mix(0.0, u_worldInnerVolumeDepth + u_popExtra, t);
        }
        // A167: a pure translation along z. The volume keeps its depth and the
        // parallax law is untouched; only the plane it hangs from moves.
        float zOff = displacement + displacementBias + u_embedOffset;
        // A174 THE TAPER. A texel may only come forward as far as it can without
        // being cut by the frustum side plane it is nearest to. Solved in a173:
        //     M  = distance from the texel to the window edge
        //     z* = H*M / (H*tan(theta) + M)
        // This is a purely SPATIAL envelope — zero on the border, largest at the
        // centre — so the near extent tapers to the glass at the frame and no
        // window violation is possible anywhere. At rest it is invisible: the
        // ray law makes screen position independent of zOff when the eye is at
        // the reference point, so the taper cannot disturb the rest frame.
        if (u_popExtra > 0.0 && zOff > 0.0) {
            vec3 Pw0 = (modelMatrix * vec4(position, 1.0)).xyz;
            float Mx = u_apertureHalf.x - abs(Pw0.x - u_apertureCenter.x);
            float My = u_apertureHalf.y - abs(Pw0.y - u_apertureCenter.y);
            // A174b THE BOUND IS TIGHT, SO IT MUST BE MADE STRICT. Substituting
            // z* back gives Emax*z/(H-z) = M exactly, i.e. |X_screen| = hw — the
            // protruding texel lands ON the window edge, and rasterisation then
            // splits the boundary pixels either way (measured: 104 px outside).
            // The margin that makes it strict is not a choice: a violation
            // smaller than ONE RENDERED PIXEL cannot be seen, so one pixel of
            // the display is the quantum here, exactly as one source quantum is
            // the quantum in a160. u_popMargin carries it in world units.
            float M  = max(0.0, min(Mx, My) - u_popMargin);
            // A176: the TAPER carries the same lambda as the request. Clamping to
            // the unscaled z* would put the border back on the bound and restore
            // the zero derivative a175 proved fatal — the slack has to be in the
            // clamp, not only in how much is asked for.
            float zStar = u_popLambda * u_popH * M / (u_popH * u_popTanTheta + M);
            zOff = min(zOff, zStar);
        }
        vec4 viewPosition;
        if (u_useRayReproject) {
            // A59f TRUE REPROJECTION. The legacy path (else) is a fronto-parallel
            // VIEW-Z push: it keeps each texel at its flat portal-plane XY and only
            // shoves view-Z, so a revealed surface is NOT placed on its reference
            // sight ray -> lateral error growing to the frame edges, present even
            // head-on, and a flat card never rotates. Instead place the texel on the
            // ray from the fixed reference (authoring) eye through its portal point,
            // at world depth zOff, in an EYE-INDEPENDENT world frame. The live camera
            // then reprojects this genuine 3D point with correct parallax from any
            // position -- the real anamorphic/backward projection.
            vec3 Pw = (modelMatrix * vec4(position, 1.0)).xyz;   // portal-plane vertex, world
            float H = u_refEye.z - Pw.z;                          // ref eye -> portal distance
            if (abs(H) < 1e-4) H = (H < 0.0 ? -1e-4 : 1e-4);
            vec3 dir = Pw - u_refEye;
            float s = (H - zOff) / H;                             // so Sw.z == Pw.z + zOff
            vec3 Sw = u_refEye + dir * s;
            vWorldPos = Sw;
            viewPosition = viewMatrix * vec4(Sw, 1.0);
        } else {
            viewPosition = modelViewMatrix * vec4(position, 1.0);
            viewPosition.z += zOff;
            // The legacy path pushes VIEW z, so there is no exact world point.
            // The portal-plane point offset along world z is the closest honest
            // statement, and this path is deprecated (a59f).
            vec3 Pl = (modelMatrix * vec4(position, 1.0)).xyz;
            vWorldPos = vec3(Pl.xy, Pl.z + zOff);
        }
        vViewPosition = viewPosition.xyz;
        gl_Position = projectionMatrix * viewPosition;
        vClipW = gl_Position.w;
    `;
     const alphaDiscardLogicGLSL = `
        if (u_hasAlphaMap) {
            float alphaValue = texture2D(u_alphaMap, vUv).r;
            if (alphaValue < 0.1) { 
                 // discard; 
            }
        }
    `;
    
    // A171 THE APERTURE CROP — the window done by geometry instead of by paint.
    //
    // a170 kept the outer matte in fullscreen because REMOVING it exposed the
    // scene-extension apron across 100% of the letterbox at rest. But an opaque
    // matte is a poor way to be a window: it can only hide things by painting
    // over them, so it cannot be taken away.
    //
    // A real window hides by GEOMETRY. A point behind the window plane is
    // visible only if the ray from the eye to it passes through the aperture.
    // That is the entire rule, it is exact, and it needs no constant: intersect
    // the eye->fragment ray with the aperture plane and test the crossing
    // against the aperture rect.
    //
    // The apron is bounded by this for free. Its whole purpose is to fill
    // beyond-frame reveals, and a beyond-frame reveal is by definition source
    // that has slid INTO the aperture — so a correctly-working apron never needs
    // to be outside it, and anything of it that is outside is padding on display.
    //
    // Fragments IN FRONT of the aperture plane are deliberately NOT cropped.
    // That is the a170 spill: a window occludes what is behind it, never what is
    // in front of it, so the inner volume keeps breaking out.
    const apertureCropGLSL = `
        if (u_apertureCrop > 0.5 && vWorldPos.z <= u_apertureZ) {
            float denom = vWorldPos.z - u_eyeWorld.z;
            if (abs(denom) > 1e-6) {
                float t = (u_apertureZ - u_eyeWorld.z) / denom;
                vec2 X = u_eyeWorld.xy + (vWorldPos.xy - u_eyeWorld.xy) * t;
                vec2 d = abs(X - u_apertureCenter) - u_apertureHalf;
                if (max(d.x, d.y) > 0.0) discard;
            }
        }
    `;

    const peekHighlightLogicGLSL = `
        if (u_splitPeekActive) {
            float depthDiff = vNormalizedDepth - u_splitPeekValue;
            if (abs(depthDiff) < u_depthPeekTolerance) {
               originalColor.rgb = mix(originalColor.rgb, vec3(0.2, 1.0, 0.2), 0.7);
            } else if (depthDiff < 0.0) {
               originalColor.rgb *= 0.5;
            }
        } else if (u_depthPeekActive && abs(vNormalizedDepth - u_depthPeekValue) < u_depthPeekTolerance) {
               originalColor.rgb = mix(originalColor.rgb, vec3(0.8, 0.2, 0.8), 0.5);
        }
    `;

    // SD-REGION HIGHLIGHT (A36): preview of exactly where diffusion will
    // inpaint. On the plate, texels inside the all-viewpoint disocclusion
    // mask are tinted on a depth ramp (far = cyan, near = amber) with a
    // bright rim at the region boundary; foreground layers dim so the
    // regions glow through at rest.
    // A210 THE COLOUR SAYS INPAINT OR OUTPAINT, BY THE USER'S RULE: anything
    // OUTSIDE the source frame is OUTPAINT (orange), anything inside is
    // INPAINT — an interior disocclusion (cyan). The frame is the content
    // mesh rect in world x/y (u_frameC/u_frameH, synced per frame), and the
    // test runs on the fragment's WORLD position (vWorldPos, a171), so it is
    // geometric and mode-independent: any plate / skirt / plane fragment that
    // lies beyond the source frame is padding standing in for outpaint and is
    // marked orange even though it has geometry and colour — which is exactly
    // the demand the old mask-only tint could never see (the mask lives in
    // source UV and cannot address beyond-frame space at all). The previous
    // depth-graded tint is retired: colour now carries the in/out semantic.
    const sdHighlightLogicGLSL = `
        if (u_sdHighlight) {
            if (u_isBackgroundLayer) {
                // A210b: for CONTENT-BEARING fragments the classification is
                // the content's own x/y against the frame rect — skirt/apron
                // padding beyond the frame stands in for beyond-frame source
                // and is outpaint wherever the eye happens to be. (The ray
                // test belongs to the backdrop, which carries no content and
                // is classified at the far volume extent it sits on.)
                bool outFrame = (abs(vWorldPos.x - u_frameC.x) > u_frameH.x + 1e-5) ||
                                (abs(vWorldPos.y - u_frameC.y) > u_frameH.y + 1e-5);
                if (outFrame) {
                    originalColor.rgb = mix(originalColor.rgb, vec3(1.0, 0.45, 0.05), 0.65);
                } else {
                    float sdm = texture2D(u_sdMask, vUv).r;
                    if (sdm > 0.5) {
                        float edge = 0.0;
                        for (int k = 0; k < 4; k++) {
                            vec2 o = (k == 0) ? vec2( 2.0, 0.0) : (k == 1) ? vec2(-2.0, 0.0)
                                   : (k == 2) ? vec2(0.0,  2.0) : vec2(0.0, -2.0);
                            if (texture2D(u_sdMask, vUv + o * u_sdMaskTexel).r < 0.5) edge = 1.0;
                        }
                        originalColor.rgb = mix(originalColor.rgb, vec3(0.15, 0.75, 1.0), 0.55);
                        if (edge > 0.5) originalColor.rgb = mix(originalColor.rgb, vec3(1.0), 0.75);
                    }
                }
            } else {
                originalColor.rgb *= 0.35;   // dim FG so the regions read through
            }
        }
    `;

    // Mode-specific shaders (Updated to use the unified gap logic)
    if (mode === "image") {
        specificUniforms = { map: { value: mainTexture }, displacementMap: { value: depthTextureForMode } };
        vertexShaderSource = `
            ${baseVertexShaderPrefix} uniform sampler2D displacementMap;
            void main() { vUv = uv; vFoldAt = aFoldAt; vNormalizedDepth = texture2D(displacementMap, vUv).r; ${viewSpaceDisplacementLogic} vClip = gl_Position; }`;

        fragmentShaderSource = `
            ${fragmentShaderHead} uniform sampler2D map; uniform sampler2D displacementMap;
            float getDepth(vec2 uv) { return texture2D(displacementMap, uv).r; }
            void main() {
                ${apertureCropGLSL}
                vec4 originalColor = texture2D(map, vUv);
                // A171: the u_ignoreSrcAlpha branch is gone. It existed only for
                // the a111 cap cards, whose alpha was zero exactly where they were
                // needed; a169 deleted the cards, and nothing has set the uniform
                // since, so it was a dead branch carrying a live explanation.
                ${alphaDiscardLogicGLSL}
                if (originalColor.a < 0.01) discard;
                // A58: quick-bake plate is HOLE-ONLY. Render only inside the
                // dilated disocclusion band (the "SD regions"); everywhere the
                // foreground stays intact the plate is unwanted full-clone
                // backstop, so discard it -> the plate becomes floating islands
                // that plug exactly the reveals, at the background depth behind
                // the occluder.
                // A59b: only the in-frame CORE is hole-only. Outside [0,1] is the
                // scene-extension margin (edge-replicated backdrop) which must stay
                // visible, so the island discard is gated to vUv in [0,1].
                if (u_useBgIslands && vUv.x >= 0.0 && vUv.x <= 1.0 && vUv.y >= 0.0 && vUv.y <= 1.0 &&
                    texture2D(u_bgIslandMask, vUv).r < 0.5) discard;
                ${unifiedGapLogicGLSL}
                ${peekHighlightLogicGLSL}
                ${sdHighlightLogicGLSL}
                gl_FragColor = originalColor;
            }`;

    } else if (mode === "sidebyside") {
        specificUniforms = {
            videoTexture: { value: mainTexture },
            rgbVideoCoords: { value: new THREE.Vector4(defaultRgbVideoCoords.x, defaultRgbVideoCoords.y, defaultRgbVideoCoords.width, defaultRgbVideoCoords.height) },
            depthMapCoords: { value: new THREE.Vector4(defaultDepthMapCoords.x, defaultDepthMapCoords.y, defaultDepthMapCoords.width, defaultDepthMapCoords.height) },
            videoDimensions: { value: new THREE.Vector2(videoContentElementGlobal.videoWidth || 1920, videoContentElementGlobal.videoHeight || 540) },
        };
         vertexShaderSource = `
            ${baseVertexShaderPrefix} uniform sampler2D videoTexture; uniform vec4 depthMapCoords; uniform vec2 videoDimensions;
            void main() { vUv = uv; vec2 dUV = vec2((depthMapCoords.x + depthMapCoords.z*uv.x)/videoDimensions.x, (depthMapCoords.y + depthMapCoords.w*uv.y)/videoDimensions.y); vNormalizedDepth = texture2D(videoTexture, dUV).r; ${viewSpaceDisplacementLogic} }`;
        
        fragmentShaderSource = `
            ${fragmentShaderHead} uniform sampler2D videoTexture; uniform vec4 rgbVideoCoords; uniform vec4 depthMapCoords; uniform vec2 videoDimensions;
            float getDepth(vec2 planeUv) {
                vec2 dUv = vec2((depthMapCoords.x + depthMapCoords.z * planeUv.x) / videoDimensions.x, (depthMapCoords.y + depthMapCoords.w * planeUv.y) / videoDimensions.y);
                return texture2D(videoTexture, dUv).r;
            }
            void main() {
                ${apertureCropGLSL}
                vec2 rgbSampleUv = vec2((rgbVideoCoords.x + rgbVideoCoords.z * vUv.x) / videoDimensions.x, (rgbVideoCoords.y + rgbVideoCoords.w * vUv.y) / videoDimensions.y);
                vec4 originalColor = texture2D(videoTexture, rgbSampleUv);
                ${alphaDiscardLogicGLSL}
                if (originalColor.a < 0.01) discard;
                ${unifiedGapLogicGLSL}
                ${peekHighlightLogicGLSL}
                ${sdHighlightLogicGLSL}
                gl_FragColor = originalColor;
            }`;

    } else if (mode === "separated") {
         specificUniforms = { rgbTexture: { value: mainTexture }, depthTexture: { value: depthTextureForMode } };
        vertexShaderSource = `
            ${baseVertexShaderPrefix} uniform sampler2D depthTexture;
            void main() { vUv = uv; vNormalizedDepth = texture2D(depthTexture, vUv).r; ${viewSpaceDisplacementLogic} }`;
        
        fragmentShaderSource = `
            ${fragmentShaderHead} uniform sampler2D rgbTexture; uniform sampler2D depthTexture;
            float getDepth(vec2 uv) { return texture2D(depthTexture, uv).r; }
            void main() {
                ${apertureCropGLSL}
                vec4 originalColor = texture2D(rgbTexture, vUv);
                ${alphaDiscardLogicGLSL} 
                if (originalColor.a < 0.01) discard; 
                ${unifiedGapLogicGLSL}
                ${peekHighlightLogicGLSL}
                ${sdHighlightLogicGLSL}
                gl_FragColor = originalColor;
            }`;
    }

    Object.assign(materialUniforms, specificUniforms);

    return new THREE.ShaderMaterial({
        uniforms: materialUniforms,
        vertexShader: vertexShaderSource,
        fragmentShader: fragmentShaderSource,
        side: THREE.DoubleSide,
        transparent: true,
        depthWrite: true,
        depthTest: true,
        extensions: { derivatives: true }
    });
}

/**
 * Creates a "Ghost" filler mesh.
 * FIX: Directly edits the custom ShaderMaterial string (since chunks don't exist).
 * Forces depth to 0.0 (Background) to create a FLAT plate, then dilates it.
 */
function createGhostMesh(originalMesh) {
    if (!originalMesh || !originalMesh.geometry || !originalMesh.material) return null;

    const ghostGeometry = originalMesh.geometry.clone();
    const ghostMaterial = originalMesh.material.clone();

    ghostMaterial.side = THREE.BackSide;
    
    // --- 1. FLATTEN & DILATE (Vertex Shader) ---
    let vs = ghostMaterial.vertexShader;
    
    // A. Force Depth to 0.0 (Background)
    // This kills the "Ramp". The mesh will now sit flat at the furthest depth plane.
    // We look for the line: vNormalizedDepth = texture2D(...).r;
    vs = vs.replace(
        /vNormalizedDepth\s*=\s*texture2D\([^)]+\)\.r;/g, 
        'vNormalizedDepth = 0.0;' 
    );

    // B. Dilate XY (Stretch width/height)
    // We inject logic to push vertices outward from the center.
    const dilationLogic = `
        // Dilation: Push vertices outwards to create a rim
        vec2 fromCenter = uv - 0.5;
        vec3 dilatedPos = position;
        // 0.04 = 4% expansion. Increase this if you still see gaps.
        dilatedPos.xy += normalize(fromCenter) * 0.04; 
    `;
    
    // Inject the variable definition at the start of main()
    vs = vs.replace('void main() {', 'void main() { ' + dilationLogic);
    
    // Apply the dilated position to the modelViewMatrix calculation
    // Your shader uses: vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);
    vs = vs.replace(
        'vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);',
        'vec4 viewPosition = modelViewMatrix * vec4(dilatedPos, 1.0);'
    );

    ghostMaterial.vertexShader = vs;

    // --- 2. DARKEN (Fragment Shader) ---
    // Make it look like a shadow/void filling.
    let fs = ghostMaterial.fragmentShader;
    fs = fs.replace(
        'gl_FragColor = originalColor;',
        `
        // Darken the ghost to 30% brightness
        gl_FragColor = vec4(originalColor.rgb * 0.3, 1.0);
        `
    );
    
    ghostMaterial.fragmentShader = fs;
    ghostMaterial.needsUpdate = true;

    const ghostMesh = new THREE.Mesh(ghostGeometry, ghostMaterial);
    ghostMesh.renderOrder = -5; // Force it to draw behind the main mesh
    
    return ghostMesh;
}

