        const setH = (mm) => { if (mm && mm.uniforms && mm.uniforms.u_sdHighlight) mm.uniforms.u_sdHighlight.value = on; };
        if (typeof bgLayerMesh !== 'undefined' && bgLayerMesh) setH(bgLayerMesh.material);
