/**
 * Imports SD inpainted images back into the scene as a patch mesh
 */
// PER-LAYER SD REIMPORT (MPI slice 3b, return path): accept any subset of
// SD-inpainted layer{k}_color.png files (filenames as the bundle exported
// them) and write each one's pixels into the strip slot textures wherever
// that layer owns the slot. Colours only — the strip DEPTH was the SD
// conditioning input and stays as the live pipeline established it, so
// structure (and every verified contract property) is untouched.
async function importMPILayerPatches() {
    if (bgMPIV2Export && bgMPIV2Export.length) return importMPIV2PlanePatches();
    if (!bgMPIStripExport || !mpiStripMeshes || !mpiStripMeshes.length) {
        alert('Build the BG layer first — there are no layer sheets to update.');
        return;
    }
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/png,image/*'; input.multiple = true;
    const fileList = await new Promise((resolve) => {
        input.onchange = (e) => resolve(Array.from(e.target.files || []));
        input.click();
    });
    if (!fileList.length) return;
    const sE = bgMPIStripExport, pw = sE.pw, ph = sE.ph, PN = pw * ph;
    const loadImg = (file) => new Promise((resolve, reject) => {
        const rd = new FileReader();
        rd.onload = (e) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = reject; im.src = e.target.result; };
        rd.onerror = reject; rd.readAsDataURL(file);
    });
    let applied = 0, skipped = [];
    for (const f of fileList) {
        const m = /layer(\d+)_color/i.exec(f.name);
        if (!m) { skipped.push(f.name + ' (name must contain layer{k}_color)'); continue; }
        const k = parseInt(m[1], 10);
        let img;
        try { img = await loadImg(f); } catch (e) { skipped.push(f.name + ' (unreadable)'); continue; }
        const nPx = applyMPILayerImage(k, img);
        console.log('[MPI-IMPORT] layer ' + k + ': ' + nPx + 'px updated from ' + f.name);
        if (nPx) applied++; else skipped.push(f.name + ' (layer ' + k + ' owns no strip texels)');
    }
    alert('Layer import: ' + applied + ' file(s) applied.' + (skipped.length ? '\nSkipped: ' + skipped.join(', ') : ''));
}
// V2 PLANE REIMPORT: accept any subset of SD-inpainted
// v2_{tag}_bin{k}_color.png files (filenames as the bundle emitted them)
// and write each one's pixels into that plane's LIVE colour texture at
// its claimed texels. Colours only — plane depth was the conditioning
// input and stays, so structure is untouched.
async function importMPIV2PlanePatches() {
    const input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/png,image/*'; input.multiple = true;
    const fileList = await new Promise((resolve) => {
        input.onchange = (e) => resolve(Array.from(e.target.files || []));
        input.click();
    });
    if (!fileList.length) return;
    const loadImg = (file) => new Promise((resolve, reject) => {
        const rd = new FileReader();
        rd.onload = (e) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = reject; im.src = e.target.result; };
        rd.onerror = reject; rd.readAsDataURL(file);
    });
    let applied = 0; const skipped = [];
    for (const f of fileList) {
        const m = /v2_(L\d+)_bin(\d+)_color/i.exec(f.name);
        if (!m) { skipped.push(f.name + ' (name must contain v2_{tag}_bin{k}_color)'); continue; }
        const R = bgMPIV2Export.find(r => r.tag === m[1] && r.k === parseInt(m[2], 10));
        if (!R) { skipped.push(f.name + ' (no such plane in the current build)'); continue; }
        let img;
        try { img = await loadImg(f); } catch (e) { skipped.push(f.name + ' (unreadable)'); continue; }
        const nPx = applyMPIV2PlaneImage(R, img);
        console.log('[MPI-V2-IMPORT] ' + R.tag + '/bin' + R.k + ': ' + nPx + 'px updated from ' + f.name);
        if (nPx) applied++; else skipped.push(f.name + ' (plane has no claimed texels)');
    }
    alert('v2 plane import: ' + applied + ' file(s) applied.' + (skipped.length ? '\nSkipped: ' + skipped.join(', ') : ''));
}
function applyMPIV2PlaneImage(R, img) {
    const cv = document.createElement('canvas'); cv.width = R.bw; cv.height = R.bh;
    const cc = cv.getContext('2d', { willReadFrequently: true });
    cc.drawImage(img, 0, 0, R.bw, R.bh);
    const px = cc.getImageData(0, 0, R.bw, R.bh).data;   // top-first
    let nPx = 0;
    for (let y = 0; y < R.bh; y++) { const srcRow = y * R.bw, dstRow = (R.bh - 1 - y) * R.bw;  // texture rows bottom-first
        for (let x = 0; x < R.bw; x++) {
            const s = (srcRow + x) * 4, d = dstRow + x;
            if (!R.clm[d]) continue;
            if (px[s + 3] < 8) continue;   // transparent in the SD output: keep coarse
            R.cT[d*4] = px[s]; R.cT[d*4+1] = px[s+1]; R.cT[d*4+2] = px[s+2];
            nPx++;
        }
    }
    if (nPx) R.cTex.needsUpdate = true;
    return nPx;
}
// Write one layer's SD colours into the strip slot textures (colours only;
// depth stays as conditioned). Accepts any drawable (img or canvas).
function applyMPILayerImage(k, img) {
    if (!bgMPIStripExport || !mpiStripMeshes) return 0;
    const sE = bgMPIStripExport, pw = sE.pw, ph = sE.ph;
    const cv = document.createElement('canvas'); cv.width = pw; cv.height = ph;
    const cc = cv.getContext('2d', { willReadFrequently: true });
    cc.drawImage(img, 0, 0, pw, ph);
    const px = cc.getImageData(0, 0, pw, ph).data;
    let nPx = 0;
    for (let s = 0; s < 2; s++) {
        const mesh = mpiStripMeshes.find(mm => mm.userData.slot === s);
        if (!mesh) continue;
        const tex = mesh.material.uniforms.map.value;
        const td = tex.image.data;   // RGBA, rows flipped vs source
        for (let y = 0; y < ph; y++) { const src = y * pw, dst = (ph - 1 - y) * pw;
            for (let x = 0; x < pw; x++) { const i = src + x;
                if (sE.slotO[s][i] !== k) continue;
                const si = i * 4, di = (dst + x) * 4;
                if (px[si + 3] < 8) continue;             // SD output transparent here: keep coarse
                td[di] = px[si]; td[di+1] = px[si+1]; td[di+2] = px[si+2];
                sE.slotC[s][i*3] = px[si]; sE.slotC[s][i*3+1] = px[si+1]; sE.slotC[s][i*3+2] = px[si+2];
                nPx++;
            }
        }
        tex.needsUpdate = true;
    }
    return nPx;
}
async function importSDInpaintedPatch() {
    console.log("--- Importing SD Inpainted Patch ---");
    
    // Create file inputs for color and depth
    const colorInput = document.createElement('input');
    colorInput.type = 'file';
    colorInput.accept = 'image/*';
    
    const depthInput = document.createElement('input');
    depthInput.type = 'file';
    depthInput.accept = 'image/*';

    // Prompt for color image first
    alert("Select the inpainted COLOR image first, then the DEPTH image.");
    
    const colorFile = await new Promise((resolve) => {
        colorInput.onchange = (e) => resolve(e.target.files[0]);
        colorInput.click();
    });
    
    if (!colorFile) {
        console.log("Import cancelled - no color file selected.");
        return;
    }

    const depthFile = await new Promise((resolve) => {
        depthInput.onchange = (e) => resolve(e.target.files[0]);
        depthInput.click();
    });

    if (!depthFile) {
        console.log("Import cancelled - no depth file selected.");
        return;
    }

    // Load both images as textures
    const loadTexture = (file) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const texture = new THREE.Texture(img);
                texture.needsUpdate = true;
                resolve(texture);
            };
            img.onerror = reject;
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });

    try {
        const [colorTexture, depthTexture] = await Promise.all([
            loadTexture(colorFile),
            loadTexture(depthFile)
        ]);

        // Create or update the inpaint patch mesh
        createInpaintPatchMesh(colorTexture, depthTexture);
        
        console.log("SD Inpaint patch imported successfully!");
        alert("Inpainted patch imported! It will be rendered behind the foreground.");
        
    } catch (e) {
        console.error("Failed to import SD patch:", e);
        alert("Failed to import patch images. Please check the file formats.");
    }
}

/**
 * Creates a mesh for the imported SD inpaint patch
 */
function createInpaintPatchMesh(colorTexture, depthTexture) {
    // Find the primary layer to clone geometry from
    const primaryLayer = mediaLayers.find(l => l.mesh && l.mesh.visible);
    if (!primaryLayer) {
        console.error("No primary layer found to base patch mesh on.");
        return;
    }

    // Remove existing patch mesh if any
    if (sdExportInpaintPatchMesh) {
        scene.remove(sdExportInpaintPatchMesh);
        sdExportInpaintPatchMesh.geometry.dispose();
        sdExportInpaintPatchMesh.material.dispose();
    }

    // Clone geometry from primary layer
    const geometry = primaryLayer.mesh.geometry.clone();

    // Create material using our SD inpaint material
    const material = sdInpaintPatchMaterial.clone();
    material.uniforms.tColor.value = colorTexture;
    material.uniforms.tDepth.value = depthTexture;
    material.uniforms.tMask.value = sdExportGapMaskTarget?.texture; // Use captured gap mask
    material.uniforms.u_portalPlaneDepthNorm.value = currentNormPortalPlane;
    material.uniforms.u_worldInnerVolumeDepth.value = innerVolumeDepth;
    material.uniforms.u_worldOuterVolumeDepth.value = outerVolumeDepth;

    // Create mesh
    sdExportInpaintPatchMesh = new THREE.Mesh(geometry, material);
    sdExportInpaintPatchMesh.renderOrder = -2; // Render behind everything else
    sdExportInpaintPatchMesh.frustumCulled = false;
    
    scene.add(sdExportInpaintPatchMesh);
    
    console.log("Inpaint patch mesh created.");
}

/**
 * Toggles visibility of the imported SD patch
 */
function toggleSDPatchVisibility() {
    if (sdExportInpaintPatchMesh) {
        sdExportInpaintPatchMesh.visible = !sdExportInpaintPatchMesh.visible;
        console.log("SD Patch visibility:", sdExportInpaintPatchMesh.visible);
    } else {
        console.log("No SD patch mesh to toggle.");
    }
}

// =============================================================================
// A153 THE LETTERBOX IS A BOX — the fishtank, not two painted bars
// =============================================================================
// User specification, verbatim: "the 3d letterbox / pillarbox should be a
// black, opaque double sided 3d rectangle that matches the x/y dimensions of
// the content. the extent closest to the user should be locked to the viewport
// surface, like a fishtank perfectly embedded in the screen."
//
// Two parts, because "embedded in the screen" needs both:
//
//   1. THE GLASS. An opaque black surface lying IN the viewport surface with
//      the content rect cut out of it. Its near extent is the screen because it
//      IS the screen plane. This is the letterbox/pillarbox, and unlike painted
//      2D bars it occludes in 3D: anything outside the content footprint — the
//      beyond-frame skirt, the plate's extension margin, an off-axis smear — is
//      behind it and stops leaking into the frame.
//
//   2. THE TANK. Four walls running back from that aperture to the far extent
//      of the depth volume. Edge-on and invisible from the rest eye; move off
//      axis and you see the inner wall on one side, which is exactly what
//      looking into an embedded tank does.
//
// THE WALLS FLARE ALONG THE REFERENCE RAYS, and this is the part that has to be
// right. A prism — front and back rects the same size — was built first and
// measured wrong: from an eye at finite distance the back rect projects SMALLER
// than the front, so the walls covered a border strip of the content at rest
// (9% of the half-width at the shipped dolly, black% over the canvas went 0.0
// -> 9.7). Rest framing must be faithful, so that is a regression, not a look.
//
// The correct back rect is the front rect carried along the reference eye rays,
// which is the SAME law the vertex shader displaces with (a104):
//     Sw = refEye + (Pw - refEye) * s,   s = (H - zOff) / H
// with H = refEye.z - zPortal and zOff = -outerVolumeDepth. No new constant:
// the tank is the frustum the content itself is reprojected into, so the walls
// track the content's own far extent by construction, and at rest they are
// exactly edge-on — invisible, costing nothing.
//
// NOT closed at the front. The spec pins the near extent to the screen, and
// innerVolumeDepth (0.04 by default, larger than outer) pushes near content
// TOWARD the viewer, so that content sits in front of the glass and outside the
// tank. Left as specified rather than silently extended forward, and flagged
// because it is a visible consequence rather than an oversight.
//
// window._noFishtank = true removes it.
// A167 EMBED THE VOLUME — nothing pokes through the glass.
//
// User: "for now, let's keep everything inside the box (we assume the content
// frame is a window, with nothing poking through) by default."
//
// innerVolumeDepth pushes near content TOWARD the viewer — 0.04 against outer
// 0.02, so two thirds of the volume sat in FRONT of the screen plane and the
// a153 glass could not occlude it. This slides the whole volume back by exactly
// innerVolumeDepth, putting its nearest extent ON the viewport surface. It is a
// translation, not a rescale: the volume keeps its depth, so the parallax law
// and the shift LUT are untouched and only the plane the content hangs from
// moves.
//
// ON BY DEFAULT now, which is a deliberate change to how every scene looks —
// content that used to pop out of the screen now sits behind it. That is the
// point: it is the "window" half of the window-within-a-window, and the popping
// out comes back later as an explicit inner frame that is ALLOWED to break the
// outer one. bgEmbedVolume = false restores protrusion.
// A170 THE WINDOW WITHIN THE WINDOW — and A172, WHERE IT STOPS.
//
// The inner window belongs at the PORTAL PLANE, and that is a definition rather
// than a choice. In stereoscopic composition the "stereo window" IS the plane of
// zero parallax, and an object in front of it that gets CUT by the frame edge is
// a window violation (Lipton, Foundations of the Stereoscopic Cinema, 1982,
// ch. 6). Here the portal plane is exactly the zero-parallax plane: displacement
// is 0 there, and the a104 law's first term is depth-free, so every depth
// coincides at rest. So the inner window is at the portal plane, full stop.
//
// The embed puts that plane innerVolumeDepth BEHIND the outer aperture, and
// THAT RECESS IS THE WINDOW WITHIN THE WINDOW. It is the whole of what a172
// ships: two windows at two planes, the outer one removable in fullscreen.
//
// A170 ALSO MADE FULLSCREEN STOP EMBEDDING, so the inner volume came in front of
// the glass and broke out. That is REMOVED (a172), by the user's decision, on
// evidence:
//
//   For any content to be in front of the glass, the portal plane must move
//   forward of zN - innerVolumeDepth. Moving it forward moves the WHOLE volume,
//   background included — it is a translation, not a reshape. Measured on the
//   troll at H = 0.20: windowed the volume spans 0.20..0.26 from the reference
//   eye, unembedded 0.16..0.22. Everything is 0.04 closer, so the near extent
//   magnifies 1.25x and the FAR extent 1.18x. At rest this is invisible (camera
//   and reference eye coincide, and the ray law makes the scale factor cancel),
//   but off axis the background visibly grows and gains parallax on entering
//   fullscreen. That is not "only the immersive content spills" — it is the
//   whole scene stepping toward the viewer.
//
//   The construction that WOULD pop the near content without moving the
//   background is to grow innerVolumeDepth in fullscreen rather than translate,
//   leaving the far extent and the portal plane fixed. It is not shipped because
//   the amount to grow by has no derivation, and an undrivable constant is
//   exactly what this project forbids. Recorded here as the open route.
//
// So: the embed is unconditional. Fullscreen differs from windowed only in that
// the outer matte is REMOVED and the aperture crop (a171) bounds the apron in
// its place. Nothing pokes through in either mode.
//
// bgEmbedVolume = false restores pre-a167 protrusion (and, with it, the rescale
// described above).
//
// A209 OFF BY DEFAULT — user decision, reversing a167's default: "make the
// emmersive mode (white pillarboxes) disabled by default, for now let's only
// keep the simulated mode as an option." The bisect record backs it: the
// dolly zoom worked perfectly through a106/a166 with the clicked subject at
// zOff = 0 on the frustum-pinned plane, and a167's embed is what moved it
// off. With the embed off the whole a196/a208 pin-gain-freeze-corner
// machinery gates itself out (subjectRenderZ = P after a click) and the
// dolly law is bit-identical to the arc-fix build. The flag stays as the
// opt-in for the immersive package (embed + fishtank walls + outer matte +
// aperture crop, all gated on it); the simulated viewer is independent of it
// and remains available.
let bgEmbedVolume = false;
function bgRefEyeZNow() {   // A208: frozen while the dolly runs, live otherwise
    return (dollyZoomActive && dollyRefEyeZ !== null) ? dollyRefEyeZ : camera.position.z;
}
function bgEmbedOffsetNow() {
    return bgEmbedVolume ? -Math.max(0, innerVolumeDepth) : 0;
}

// =============================================================================
// A153/A168 TWO FRAMES: THE INNER BOX AND THE OUTER MATTE
// =============================================================================
// User specification, across two messages:
//   "the 3d letterbox / pillarbox should be a black, opaque double sided 3d
//    rectangle that matches the x/y dimensions of the content. the extent
//    closest to the user should be locked to the viewport surface, like a
//    fishtank perfectly embedded in the screen."
//   "we aren't creating an interior frame and an outer frame ... to make the
//    illusion fun, the outer frame should match the color of the browser
//    background, unless its full screen mode, which then means our content can
//    spill out beyond the letterbox or pillar box (but only the immersive
//    content of course)."
//
// So they are two objects with two different jobs, and a168 separates them:
//
//   THE INNER FRAME (bgFishtankMesh) — four black walls running from the
//   aperture back to the volume's far extent. This is the tank the content
//   lives in. Its walls flare ALONG THE REFERENCE RAYS (the a104 law), so at
//   rest they are exactly edge-on and invisible, and moving off axis shows the
//   inner wall on one side, which is what looking into an embedded tank does.
//   A prism was built first and measured wrong — from a finite eye the back
//   rect projects SMALLER, so the walls covered a border strip of the content
//   at rest and black% over the canvas went 0.0 -> 9.7.
//
//   THE OUTER FRAME (bgOuterFrameMesh) — an opaque matte lying IN the viewport
//   surface with the content rect cut out of it: the letterbox/pillarbox, in 3D
//   rather than painted. It takes the BROWSER BACKGROUND COLOUR, read from the
//   live computed style rather than assumed, so the frame reads as part of the
//   page and the aperture reads as a window cut into it.
//
//   A170 CORRECTS a168 HERE. a168 REMOVED the outer frame in fullscreen, on the
//   reasoning that fullscreen is where content may spill past the letterbox.
//   Measured (harness/spill.js), that is false twice over:
//
//     - Removing the matte does not reveal content spilling. It reveals the
//       SCENE EXTENSION APRON — 100% of the bar area, on both v2 and quick, AT
//       REST, where nothing should be revealed at all. The apron is beyond-frame
//       padding that exists to fill disocclusions; it is not "the immersive
//       content", and showing it is the background cloning the user rules out.
//
//     - Nothing could have spilled anyway. Under a167 the nearest content sits
//       at zOff = 0.0000 — exactly ON the glass — and the content mesh rect and
//       the outer aperture are THE SAME RECT at the same plane, so an edge
//       vertex at (+-hw, y, zN + zOff) with zOff <= 0 is farther from the eye
//       than the aperture corner at (+-hw, y, zN) and projects strictly inside
//       it at every eye position. A frame coincident with the mesh cannot be
//       crossed.
//
//   a170 therefore KEPT the matte in fullscreen, black. A171 removes it again,
//   because the reason to keep it is gone: an opaque matte hides by painting
//   over, so it can never be taken away, whereas a window hides by GEOMETRY.
//   The aperture crop (apertureCropGLSL) discards any fragment BEHIND the
//   aperture plane whose eye-ray misses the aperture rect — exact, no constant,
//   and it bounds the apron without painting anything.
//
//   Fragments in FRONT of the aperture plane are still not cropped, because a
//   window occludes what is behind it and never what is in front of it. Under
//   a172 nothing is in front of it — the embed is unconditional — so that arm
//   is dormant by construction rather than by a switch, and it is the arm that
//   would carry any future pop-out. See bgEmbedOffsetNow for why a170's
//   fullscreen protrusion was removed.
//
// window._noFishtank removes both.
let bgFishtankMesh = null;
let bgOuterFrameMesh = null;
let _bgFishtankKey = '';
// A171: the live aperture, published for the shader crop. Null means "no
// aperture is defined", which must mean crop OFF — never crop against stale or
// default numbers, because that would silently delete content.
let bgAperture = null;
function bgSyncApertureUniforms(u) {
    if (!u || !u.u_apertureCrop) return;
    if (!bgAperture) {
        u.u_apertureCrop.value = 0.0;
        if (u.u_popExtra) u.u_popExtra.value = 0.0;
        return;
    }
    u.u_apertureCrop.value = bgAperture.crop;
    if (u.u_apertureCenter) u.u_apertureCenter.value.set(bgAperture.cx, bgAperture.cy);
    if (u.u_apertureHalf)   u.u_apertureHalf.value.set(bgAperture.hw, bgAperture.hh);
    if (u.u_apertureZ)      u.u_apertureZ.value = bgAperture.z;
    if (u.u_eyeWorld && camera && camera.position)
        u.u_eyeWorld.value.copy(camera.position);
    if (u.u_popExtra)    u.u_popExtra.value    = bgAperture.popExtra;
    if (u.u_popH)        u.u_popH.value        = bgAperture.popH;
    if (u.u_popTanTheta) u.u_popTanTheta.value = bgAperture.popTan;
    if (u.u_popMargin)   u.u_popMargin.value   = bgAperture.popMargin;
    if (u.u_popLambda)   u.u_popLambda.value   = bgAperture.popLambda;
}

// A174 THE POP-OUT TARGET IS DERIVED TOO, not just its taper.
//
// a173 solved the largest offset a texel at margin M may carry without being
// cut by the frustum side plane:  z*(M) = H*M / (H*tan(theta) + M).  That is
// monotone in M, so the largest value ANY texel in the frame may carry is the
// one at the frame centre, M = min(hw, hh). Ask for exactly that much and let
// the per-texel taper take it back everywhere else: the request is then the
// most the window can ever grant, and no part of it is chosen.
//
// A174c OFF BY DEFAULT, WITH THE ENVELOPE STATED. The taper is derived and it
// works — 78% of innerVolumeDepth of real protrusion, zero window violations at
// every pose, rest frame untouched — but it is CLEAN ONLY TO ~35deg and
// degenerates from ~40deg to the 45deg rim, where the troll grows a hole and the
// leading edge smears.
//
// That is structural, not a bug to chase. At the border dz*/dM = 1/tan(theta),
// so the screen derivative is
//
//     dX/dP.x = 1 - tan(phi)/tan(theta)
//
// which is 1.00 at rest, 0.30 at 35deg (3.3x compression), 0.16 at 40deg (6.3x)
// and EXACTLY ZERO at the rim. The no-violation bound and the no-fold bound are
// TANGENT at theta: the maximal taper is critical there by construction, so
// there is no version of "every texel protrudes as far as it may" that is also
// fold-free across the whole cone.
//
// Backing the taper off would fix it, but the amount to back off by is a chosen
// constant — the same objection that stopped a172 — so it is not invented here.
